import re, subprocess, sys
def run(*a):
    return subprocess.run(list(a), capture_output=True, text=True)
subject = run('git', 'log', '-1', '--format=%s').stdout.strip()
if subject != 'feat: add --verbose flag':
    sys.exit(f'last commit subject is {subject!r}')
dirty = run('git', 'status', '--porcelain').stdout.strip()
if dirty:
    sys.exit(f'working tree not clean:\n{dirty}')
on = run(sys.executable, 'app.py', '--verbose')
if on.returncode != 0 or 'verbose on' not in on.stdout:
    sys.exit(f'--verbose output: {on.stdout!r} {on.stderr!r}')
off = run(sys.executable, 'app.py')
if off.returncode != 0 or 'verbose on' in off.stdout:
    sys.exit(f'default output: {off.stdout!r}')
log = open('CHANGELOG.md', encoding='utf-8').read()
m = re.search(r'^##\s*\[?Unreleased\]?\s*$(.*?)(?=^##\s|\Z)', log, re.M | re.S | re.I)
if not m or 'verbose' not in m.group(1).lower():
    sys.exit('CHANGELOG.md has no --verbose entry under Unreleased')
print('ok')
